import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        final long MOD = 1000000007;
        Scanner scanner = new Scanner(System.in);
        int p = scanner.nextInt();
        int k = scanner.nextInt();

        if (k == 0) {
            System.out.println(powMod(p, p - 1, MOD));
        } else if (k == 1) {
            System.out.println(powMod(p, p, MOD));
        } else {
            java.util.List<Integer> cycleList = new java.util.ArrayList<>();
            cycleList.add(1);
            while (true) {
                int last = cycleList.get(cycleList.size() - 1);
                int nextVal = (int)((long)last * k % p);
                if (nextVal == cycleList.get(0)) {
                    break;
                }
                cycleList.add(nextVal);
            }
            int cycleLength = cycleList.size();
            System.out.println(powMod(p, (p - 1) / cycleLength, MOD));
        }
        scanner.close();
    }

    private static long powMod(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}
